    pub(crate) fn compare_p_port_prototype(
        &self,
        other: &Document,
        a: &PPortPrototype,
        b: &PPortPrototype,
        path: &str,
    ) -> Result<(), String> {
        self.compare_abstract_provided_port_prototype(other, a.base(), b.base(), path)?;
        if a.get_provided_interface_t_ref() != b.get_provided_interface_t_ref() {
            return Err(format!("{path}: PROVIDED_INTERFACE_T_REF mismatch"));
        }
        Ok(())
    }

