    pub(crate) fn compare_r_port_prototype(
        &self,
        other: &Document,
        a: &RPortPrototype,
        b: &RPortPrototype,
        path: &str,
    ) -> Result<(), String> {
        self.compare_abstract_required_port_prototype(other, a.base(), b.base(), path)?;
        if a.get_may_be_unconnected() != b.get_may_be_unconnected() {
            return Err(format!("{path}: MAY_BE_UNCONNECTED mismatch"));
        }
        if a.get_required_interface_t_ref() != b.get_required_interface_t_ref() {
            return Err(format!("{path}: REQUIRED_INTERFACE_T_REF mismatch"));
        }
        Ok(())
    }

