    pub(crate) fn compare_sw_component_type(
        &self,
        other: &Document,
        a: &SwComponentType,
        b: &SwComponentType,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_type(other, a.base(), b.base(), path)?;
        let list_a = a.get_consistency_needs();
        let list_b = b.get_consistency_needs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CONSISTENCY_NEEDS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.consistency_needs.get(*x).ok_or_else(|| {
                format!("{path}.CONSISTENCY_NEEDS[{index}]: id not found in own arena")
            })?;
            let y = other.consistency_needs.get(*y).ok_or_else(|| {
                format!("{path}.CONSISTENCY_NEEDS[{index}]: id not found in other arena")
            })?;
            self.compare_consistency_needs(
                other,
                x,
                y,
                &format!("{path}.CONSISTENCY_NEEDS[{index}]"),
            )?;
        }
        let list_a = a.get_ports();
        let list_b = b.get_ports();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: PORTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.PORTS[{index}] mismatch"));
            }
        }
        let list_a = a.get_port_groups();
        let list_b = b.get_port_groups();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: PORT_GROUPS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .port_groups
                .get(*x)
                .ok_or_else(|| format!("{path}.PORT_GROUPS[{index}]: id not found in own arena"))?;
            let y = other.port_groups.get(*y).ok_or_else(|| {
                format!("{path}.PORT_GROUPS[{index}]: id not found in other arena")
            })?;
            self.compare_port_group(other, x, y, &format!("{path}.PORT_GROUPS[{index}]"))?;
        }
        let list_a = a.get_swc_mapping_constraints_refs();
        let list_b = b.get_swc_mapping_constraints_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: SWC_MAPPING_CONSTRAINTS_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.SWC_MAPPING_CONSTRAINTS_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.SWC_MAPPING_CONSTRAINTS_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.SWC_MAPPING_CONSTRAINTS_REFS[{index}]"),
            )?;
        }
        if a.get_sw_component_documentation() != b.get_sw_component_documentation() {
            return Err(format!("{path}: SW_COMPONENT_DOCUMENTATION mismatch"));
        }
        let list_a = a.get_unit_group_refs();
        let list_b = b.get_unit_group_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: UNIT_GROUP_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.UNIT_GROUP_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.UNIT_GROUP_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(other, x, y, &format!("{path}.UNIT_GROUP_REFS[{index}]"))?;
        }
        Ok(())
    }

